import { urlDoQuadro } from '../../compartilhado/arte/index.js'

export default {
  id: 'chuva-emocoes',
  nome: 'Chuva de emoções',
  descricao: 'Rostos caem do céu. Pegue só a emoção pedida!',
  habilidades: ['reconhecer-emocoes'],
  icone: urlDoQuadro('jogo_chuva'),
}
== src/jogos/cuidar-amigo/manifesto.js
import { urlDoQuadro } from '../../compartilhado/arte/index.js'

export default {
  id: 'cuidar-amigo',
  nome: 'Cuidar do amigo',
  descricao: 'Um amigo está com um sentimento. Arraste o que ajuda!',
  habilidades: ['empatia', 'causa-efeito-social'],
  icone: urlDoQuadro('jogo_cuidar'),
}
== src/jogos/memoria/manifesto.js
import icone from './assets/train.svg'

export default {
  id: 'memoria',
  nome: 'Jogo da memória',
  descricao: 'Vire as cartas e encontre os pares de figuras.',
  habilidades: ['reconhecer-emocoes'],
  icone,
}
== src/jogos/plataforma-amigo/manifesto.js
import { urlDoQuadro } from '../../compartilhado/arte/index.js'

export default {
  id: 'plataforma-amigo',
  nome: 'Plataforma do amigo',
  descricao: 'Corra, pule e ajude os amigos que encontrar pelo caminho.',
  habilidades: ['resposta-social', 'empatia'],
  icone: urlDoQuadro('jogo_plataforma'),
}
== src/jogos/quebra-cabeca/manifesto.js
import icone from './assets/icone.svg';

export default {
  id: 'quebra-cabeca',
  nome: 'Quebra-cabeça',
  descricao: 'Monte a imagem com 15 peças, olhando o modelo.',
  habilidades: ['relacao-parte-todo'],
  icone,
};
== src/jogos/sequencia/manifesto.js
import icone from './assets/locomotiva.svg';

export default {
  id: 'sequencia',
  nome: 'Complete a sequência',
  descricao: 'Olhe a fila de figuras e descubra qual vem depois.',
  habilidades: ['resposta-social', 'empatia'],
  icone,
};

