  }
  function iniciar() {
    try {
      const activity = validateActivity(ATIVIDADE, location.href)
      $('#theme').textContent = activity.theme
      scene = new MemoryScene(activity, { update, fail, reducedMotion: () => motion.matches })
      const rect = board.getBoundingClientRect()
      game = new Phaser.Game({ type: Phaser.AUTO, parent: $('#canvas-host'), width: Math.round(rect.width), height: Math.round(rect.height), transparent: true, antialias: true, audio: { noAudio: true }, input: { keyboard: false }, scale: { mode: Phaser.Scale.NONE }, scene: [scene] })
    } catch (error) { fail(error instanceof Error ? error.message : 'Não foi possível preparar a atividade.') }
  }
  action.addEventListener('click', () => {
    // o original recarregava a página; dentro do hub, só recria o jogo
    if (failed) {
      failed = false; board.hidden = false; $('#error').hidden = true
      game?.destroy(true); iniciar(); return
    }
    scene?.act()
    requestAnimationFrame(() => { const next = buttons.find((button) => button.getAttribute('aria-disabled') === 'false'); next?.focus({ preventScroll: true }) })
  })
  // Observe the board itself: resizing a parent does not always resize the window.
  const observer = new ResizeObserver(() => {
    if (game?.isBooted) { const { width, height } = board.getBoundingClientRect(); if (width && height) game.scale.resize(Math.round(width), Math.round(height)) }
  })
  observer.observe(board)
  iniciar()

  return function desmontar() {
    if (ultimo.phase === 'playing' || ultimo.phase === 'mismatch') entregar('abandoned')
    observer.disconnect()
    motion.removeEventListener('change', onMotion)
    game?.destroy(true)
    raiz.remove()
  }
}
export function validateActivity(value, baseUrl = 'https://local.invalid/activity.json') {
  if (!value || typeof value.theme !== 'string' || !value.theme.trim()) throw new Error('Informe o tema da atividade.');
  if (!Array.isArray(value.images) || value.images.length !== 3) throw new Error('Escolha exatamente três imagens diferentes.');
  const ids = new Set();
  const urls = new Set();
  const base = new URL(baseUrl);
  const images = value.images.map(image => {
    if (!image || typeof image.id !== 'string' || !image.id.trim() || ids.has(image.id.trim()) || typeof image.description !== 'string' || !image.description.trim() || typeof image.url !== 'string' || !image.url.trim()) throw new Error('Cada imagem precisa de identificador único, caminho e descrição.');
    const url = new URL(image.url, base);
    if (!['http:', 'https:'].includes(url.protocol) || url.origin !== base.origin || url.username || url.password || urls.has(url.href)) throw new Error('Use três arquivos diferentes, servidos junto com o jogo.');
    ids.add(image.id.trim()); urls.add(url.href);
    return Object.freeze({ id: image.id.trim(), url: url.href, description: image.description.trim() });
  });
  const back = value.backImage;
  if (!back || typeof back.url !== 'string' || !back.url.trim() || typeof back.description !== 'string' || !back.description.trim()) throw new Error('Escolha um símbolo para o verso, com caminho e descrição.');
  const backUrl = new URL(back.url, base);
  if (!['http:', 'https:'].includes(backUrl.protocol) || backUrl.origin !== base.origin || backUrl.username || backUrl.password) throw new Error('O símbolo do verso precisa ser servido junto com o jogo.');
  const backImage = Object.freeze({ url: backUrl.href, description: back.description.trim() });
  return Object.freeze({ theme: value.theme.trim(), images: Object.freeze(images), backImage });
}

export function shuffledDeck(images, random = Math.random) {
  const cards = images.flatMap(image => [0, 1].map(copy => Object.freeze({ ...image, key: `${image.id}-${copy}` })));
  for (let i = cards.length - 1; i > 0; i--) {
    const j = Math.floor(random() * (i + 1));
    [cards[i], cards[j]] = [cards[j], cards[i]];
  }
  return Object.freeze(cards);
}

export class MemoryRound {
  #selected = [];
  #matched = new Set();
  #phase = 'ready';
  #attempts = 0;
  constructor(images, random = Math.random) { this.cards = shuffledDeck(images, random); }
  get state() { return { phase: this.#phase, selected: [...this.#selected], matched: [...this.#matched], pairs: this.#matched.size / 2, attempts: this.#attempts, cards: this.cards }; }
  start() { if (this.#phase !== 'ready') return false; this.#phase = 'playing'; return true; }
  select(index) {
    if (this.#phase !== 'playing' || !Number.isInteger(index) || !this.cards[index] || this.#selected.includes(index) || this.#matched.has(index)) return false;
    this.#selected.push(index);
    if (this.#selected.length === 2) {
      this.#attempts++;
      const [a, b] = this.#selected;
      if (this.cards[a].id === this.cards[b].id) {
        this.#matched.add(a); this.#matched.add(b); this.#selected = [];
        if (this.#matched.size === 6) this.#phase = 'completed';
      } else this.#phase = 'mismatch';
    }
    return true;
  }
  closeMismatch() { if (this.#phase !== 'mismatch') return false; this.#selected = []; this.#phase = 'playing'; return true; }
}

export function cardLayout(width, height) {
  const columns = height > width ? 2 : 3;
  const rows = 6 / columns;
  const gap = width < 400 ? 12 : 16;
  const w = (width - gap * (columns - 1) - 16) / columns;
  const h = (height - gap * (rows - 1) - 20) / rows;
  return Array.from({ length: 6 }, (_, index) => ({ x: 8 + (index % columns) * (w + gap), y: 10 + Math.floor(index / columns) * (h + gap), width: w, height: h }));
}
